WITH valid_inventory AS (SELECT * FROM inventory WHERE quantity IS NOT NULL AND (store_id IN (3, 6) OR last_restock > '2025-07-01')), agg AS (SELECT CASE WHEN quantity >= 193 THEN 'high' WHEN quantity >= 97 THEN 'mid' ELSE 'low' END AS quantity_bucket, ROUND(AVG(quantity), 2) AS avg_quantity FROM valid_inventory GROUP BY CASE WHEN quantity >= 193 THEN 'high' WHEN quantity >= 97 THEN 'mid' ELSE 'low' END) SELECT quantity_bucket, avg_quantity FROM agg WHERE avg_quantity < 44 ORDER BY quantity_bucket LIMIT 50;
